import React, { useState } from 'react';
import { createThread, addPost } from '../utils/data';
import { useAuth } from '../contexts/AuthContext';

const ContentForm = ({ threadId, onCreate }) => {
  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');
  const { currentUser } = useAuth();

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!currentUser) {
      alert('Debes iniciar sesión para publicar o comentar.');
      return;
    }

    if (threadId) {
      const comment = { author: currentUser?.displayName || currentUser?.username || 'anon', body };
      addPost(threadId, comment);
      if (onCreate) onCreate({ type: 'comment', threadId, comment });
    } else {
      const post = createThread({ title, posts: [{ author: currentUser?.displayName || currentUser?.username || 'anon', body }] });
      if (onCreate) onCreate({ type: 'post', post });
    }

    setTitle(''); setBody('');
  };

  return (
    <form onSubmit={handleSubmit} style={{ marginTop: '0.5rem' }}>
      {!threadId && <input placeholder="Título de la publicación" value={title} onChange={(e)=>setTitle(e.target.value)} />}
      <textarea placeholder={threadId ? 'Escribe un comentario...' : 'Contenido de la nueva publicación...'} value={body} onChange={(e)=>setBody(e.target.value)} rows={4} />
      <button type="submit">Enviar</button>
    </form>
  );
};

export default ContentForm;
